function keyOf(r: any) { return [r.letting_date, r.contract_id, r.item_no, String(r.quantity)].join("|"); }

export default async function(req: Request) {
  const base44 = createClientFromRequest(req);
  const user = await base44.auth.me().catch(() => null);
  if (user && user.role !== "admin") return Response.json({ error: "Admin access required" }, { status: 403 });
  const now = new Date().toISOString();
  const existing: any[] = [];
  for (let skip = 0; skip < 5000; skip += 500) { const page = await base44.asServiceRole.entities.TDOTAggregateDemand.filter({}, "-updated_date", 500, skip).catch(() => []); existing.push(...(page || [])); if (!page || page.length < 500) break; }
  const byKey = new Map(existing.map((r: any) => [keyOf(r), r]));
  let created = 0, updated = 0, failed = 0;
  for (let i = 0; i < ROWS.length; i += 20) {
    const results = await Promise.allSettled(ROWS.slice(i, i + 20).map(async (row: any) => { const prev: any = byKey.get(keyOf(row)); const payload = { ...row, last_source_update: now }; if (prev?.id) { await base44.asServiceRole.entities.TDOTAggregateDemand.update(prev.id, payload); return "updated"; } const made = await base44.asServiceRole.entities.TDOTAggregateDemand.create(payload); if (made) byKey.set(keyOf(row), made); return "created"; }));
    for (const r of results) { if (r.status === "fulfilled" && r.value === "created") created++; else if (r.status === "fulfilled" && r.value === "updated") updated++; else failed++; }
  }
  try { await base44.asServiceRole.entities.OperationsEvent.create({ event_type: "Report", related_entity_id: "seed-tdot-2026-demand", status: failed ? "Completed with errors" : "Completed", summary: `TDOT 2026 demand seed: ${created} created, ${updated} updated, ${failed} failed from ${ROWS.length} parsed aggregate/stone line items.`, occurred_at: now }); } catch (_) {}
  return Response.json({ success: failed === 0, total: ROWS.length, created, updated, failed, ran_at: now });
}
